"""Stage 97: the build and dependency chapter (docs/63, generated by tools/analyze_build_docs.py) is current; the CMake facts it states hold; the scripts and options its recipes use exist; the dependency claims about Pillow and numpy are the real
import closures; and the clean-copy evidence (tools/check_clean_build.py) says ALL PASSED."""
import os
import re
import sys
import unittest

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
sys.path.insert(0, os.path.join(ROOT, "tools"))
import analyze_build_docs as B  # noqa: E402

DOC = os.path.join(ROOT, "docs", "63-build-and-dependencies.md")


class BuildDocs(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        with open(DOC, encoding="utf-8", newline="") as fh:
            cls.text = fh.read().replace("\r\n", "\n")

    def test_the_chapter_is_current(self):
        self.assertEqual(self.text, B.doc(), "regenerate: python -I tools/analyze_build_docs.py --doc docs/63-build-and-dependencies.md")

    def test_the_cmake_facts(self):
        f = B.cmake_facts()
        self.assertEqual((f["min"], f["std"]), ("3.16", "99"))
        self.assertIn("-Werror", f["flags"])
        self.assertIn("pacman_a8", f["exes"])
        self.assertIn("install_assets", f["exes"])
        self.assertGreaterEqual(len(f["tests"]), 39)
        self.assertEqual(len(f["tests"]), len(set(f["tests"])), "a test name is used twice")

    def test_the_scripts_and_files_the_recipes_name_exist(self):
        for t, cmds, res in B.RECIPES:
            for c in cmds:
                for m in re.finditer(r"tools/([A-Za-z0-9_]+\.(?:py|sh))", c):
                    self.assertTrue(os.path.exists(os.path.join(ROOT, "tools", m.group(1))), m.group(1))
        for m in B.RECIPE_SCRIPTS:
            self.assertTrue(os.path.exists(os.path.join(ROOT, "tools", m + ".py")), m)

    def test_the_pillow_and_numpy_claims_are_the_import_closures(self):
        # the C build, the vectors, the replays, the comparisons and the ROM rebuild reach neither module
        for m in ("make_vectors", "make_replay", "make_rom_fuzz_replays", "make_rom_edge_replays", "make_rom_bot_replay", "check_c_vs_rom", "check_behaviour", "build_rom", "check_clean_build", "run_regression"):
            self.assertEqual(B.third_party_closure(m), set(), m)
        self.assertEqual(B.third_party_closure("make_c_assets"), {"PIL"})
        self.assertEqual(B.third_party_closure("make_c_rom_layout"), {"PIL"})
        for m in B.RECIPE_SCRIPTS:
            self.assertNotIn("numpy", B.third_party_closure(m), m)

    def test_every_dependency_has_a_required_or_optional_statement(self):
        for d in B.DEPENDENCIES:
            self.assertEqual(len(d), 5)
        self.assertEqual(sum(1 for d in B.DEPENDENCIES if d[2].startswith("**required")), 4)      # the compiler, CMake, the ROM, Python (for the tests)

    def test_the_pal_os_rom_is_not_a_dependency(self):
        self.assertNotIn("PAL OS ROM", " ".join(d[0] for d in B.DEPENDENCIES))
        self.assertIn("PAL OS ROM is not used", self.text)

    def test_the_clean_copy_evidence_says_all_passed(self):
        p = os.path.join(ROOT, "analysis", "evidence-clean-build-summary.txt")
        with open(p, encoding="utf-8") as fh:
            t = fh.read()
        self.assertIn("ALL PASSED", t)
        self.assertNotIn("FAIL  ", t)


if __name__ == "__main__":
    unittest.main()
